package pe.edu.upeu.autoandes.service.impl;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import lombok.RequiredArgsConstructor; import java.util.List; import java.time.LocalDate; import pe.edu.upeu.autoandes.repository.DetalleOrdenRepository; import pe.edu.upeu.autoandes.service.ReporteService; import pe.edu.upeu.autoandes.dto.IngresoPorServicioDTO; import pe.edu.upeu.autoandes.exception.SolicitudInvalidaException;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class ReporteServiceImpl implements ReporteService {private final DetalleOrdenRepository repository;
public List<IngresoPorServicioDTO> ingresos(LocalDate desde,LocalDate hasta){if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new SolicitudInvalidaException("Desde no puede ser posterior a hasta");return repository.ingresos(desde==null?null:desde.atStartOfDay(),hasta==null?null:hasta.plusDays(1).atStartOfDay());}}
